using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 internal static class EditorTempoTests {
  static double Tone(string path){using(var input=File.OpenRead(path))using(var reader=new BinaryReader(input)){reader.ReadBytes(12);while(input.Position+8<=input.Length){string id=Encoding.ASCII.GetString(reader.ReadBytes(4));uint size=reader.ReadUInt32();if(id=="data"){int count=(int)size/2;var samples=new short[count];for(int i=0;i<count;i++)samples[i]=reader.ReadInt16();int from=Math.Min(4800,count/4),to=Math.Min(count-4800,from+48000),crossings=0;for(int i=from+1;i<to;i++)if(samples[i-1]<=0&&samples[i]>0)crossings++;return crossings*48000.0/(to-from);}input.Position+=size+(size%2);}throw new Exception("PCM data missing");}}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MediaConverterWindow converter=null;CodeEditorWindow editor=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};Action<Action,string> reject=(run,label)=>{bool failed=false;try{run();}catch(IOException){failed=true;}check(failed,label);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();
   check(Math.Abs(AudioTempo.Factors[1]-25.0/(24000.0/1001))<1e-12&&Math.Abs(AudioTempo.Factors[2]-25.0/24)<1e-12,"Film presets retain exact rational FPS ratios");check(AudioTempo.ParseDuration("01:02:03,500")==3723.5&&AudioTempo.ParseDuration("62:03.5")==3723.5&&AudioTempo.ParseDuration("3723.5")==3723.5,"Target duration accepts hours, minutes, fractional seconds and decimal comma");foreach(var value in new[]{"0","-1","NaN","1:60","1:99:00","00:00:00","999:00:00"})reject(()=>AudioTempo.ParseDuration(value),"Invalid target duration rejected: "+value);
   using(var lease=MediaProcess.Acquire()){string source=Path.Combine(root,"tone.wav");MediaProcess.Run("ffmpeg.exe",new[]{"-hide_banner","-v","error","-nostdin","-n","-f","lavfi","-i","sine=frequency=440:sample_rate=48000:duration=4","-ac","1","-c:a","pcm_s16le",source},CancellationToken.None,30);var info=MediaProcess.Probe(source,CancellationToken.None);var options=new MediaAudioOptions{Profile="wav",Channels=1,SampleRate=48000,Speed=1.25};string output=Path.Combine(root,"preserve.wav");MediaAudio.Convert(source,output,options,CancellationToken.None,null);check(Math.Abs(MediaProcess.Probe(output,CancellationToken.None).Duration-3.2)<.1&&Math.Abs(Tone(output)-440)<5,"Real atempo conversion shortens duration and preserves 440 Hz pitch");options.PreservePitch=false;output=Path.Combine(root,"pitch.wav");MediaAudio.Convert(source,output,options,CancellationToken.None,null);check(Math.Abs(MediaProcess.Probe(output,CancellationToken.None).Duration-3.2)<.05&&Math.Abs(Tone(output)-550)<5,"Real asetrate conversion changes speed and pitch, retaining 48 kHz output");options.PreservePitch=true;options.Speed=1;options.TargetDurationSeconds=3;output=Path.Combine(root,"target.wav");MediaAudio.Convert(source,output,options,CancellationToken.None,null);check(Math.Abs(MediaProcess.Probe(output,CancellationToken.None).Duration-3)<.001,"Target duration produces sample-accurate PCM length");check(MediaAudio.SpeedFilters(new MediaAudioOptions{Speed=.1},info,48000).Count>=4&&MediaAudio.SpeedFilters(new MediaAudioOptions{Speed=10},info,48000).Count>=4,"Extreme supported tempos are decomposed into safe 0.5–2.0 atempo stages");reject(()=>MediaAudio.Validate(new MediaAudioOptions{Profile="wav",Channels=1,Copy=true,Speed=1.25},info),"Tempo rejects stream copy");reject(()=>MediaAudio.Validate(new MediaAudioOptions{Profile="aac",Channels=1,KeepVideo=true,Speed=1.25},info),"Tempo rejects unchanged video timing");reject(()=>MediaAudio.SpeedFactor(new MediaAudioOptions{TargetDurationSeconds=1000},info),"Target duration rejects a speed outside the supported range");
    foreach(var profile in MediaCatalog.Audio){output=Path.Combine(root,"converted-"+profile.Id+profile.Extension);var sound=new MediaAudioOptions{Profile=profile.Id,Channels=1,SampleRate=48000,Speed=25.0/24};MediaAudio.Convert(source,output,sound,CancellationToken.None,null);check(Math.Abs(MediaProcess.Probe(output,CancellationToken.None).Duration-3.84)<.25,"Tempo converts and validates "+profile.Id);}
    string stereo=Path.Combine(root,"stereo.wav");MediaProcess.Run("ffmpeg.exe",new[]{"-hide_banner","-v","error","-nostdin","-n","-i",source,"-ac","2","-c:a","pcm_s16le",stereo},CancellationToken.None,30);string surround=Path.Combine(root,"surround-speed.ac3");MediaAudio.Convert(stereo,surround,new MediaAudioOptions{Profile="ac3",Channels=6,Upmix=true,Bitrate=384,Speed=25.0/24},CancellationToken.None,null);check(MediaProcess.Probe(surround,CancellationToken.None).Audio[0].Channels==6,"Tempo processing composes with stereo-to-5.1 surround conversion");
    converter=new MediaConverterWindow(null,new[]{source},root,false,delegate{},delegate{}){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};converter.Show();NavigationTests.Wait(converter.AnalysisTask);converter.SettingsTabs.SelectedItem=converter.SpeedTab;converter.SpeedPreset.SelectedIndex=1;check(Math.Abs(converter.AudioOptions().Speed-AudioTempo.Factors[1])<1e-12&&converter.AudioOptions().PreservePitch,"UI defaults to preserving pitch and forwards exact preset");converter.SpeedPreset.SelectedIndex=13;converter.TargetLength.Text="00:00:03.000";check(converter.AudioOptions().TargetDurationSeconds==3,"UI forwards freely entered target duration");converter.SpeedPreset.SelectedIndex=12;converter.SpeedPercent.Text="125,5";check(converter.AudioOptions().Speed==1.255,"UI accepts custom percentage with decimal comma");converter.UpdateLayout();NextStageTests.Draw(converter,Path.Combine(root,"audio-speed.png"));foreach(int size in new[]{540,560,820}){converter.Width=size<650?800:1180;converter.Height=size;converter.UpdateLayout();NavigationTests.Wait(Task.Delay(80));var queue=AdvancedToolsTests.Visual<DataGrid>(converter).Single();check(queue.ActualHeight>=64&&!AdvancedToolsTests.Visual<ScrollViewer>(queue).Any(x=>x.ComputedHorizontalScrollBarVisibility==Visibility.Visible),"Speed controls retain visible queue without horizontal scrolling at height "+size);}converter.Close();converter=null;
   }
   editor=new CodeEditorWindow(null){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};editor.Show();var file=EditorTextFile.New();file.Path=@"D:\Example\Settings.json";file.Text="{\"value\":12345678901234567890}";editor.Add(file);check(editor.EditorMenu.Items.Count==5,"Editor exposes File, Edit, View, Tools and Help menus");check(AdvancedToolsTests.Visual<Button>(editor).Any(x=>Convert.ToString(x.Content)==L.Text("codeEditor.save")),"Editor offers Save in the shared action footer");var tools=(MenuItem)editor.EditorMenu.Items[3];var format=tools.Items.OfType<MenuItem>().Single(x=>Convert.ToString(x.Header)==L.Text("codeEditor.formatJson"));format.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(editor.Current.Editor.Text.Contains("\n")&&editor.Current.Editor.IsModified,"JSON formatting works through the menu");var edit=(MenuItem)editor.EditorMenu.Items[1];edit.Items.OfType<MenuItem>().Single(x=>Convert.ToString(x.Header)==L.Text("codeEditor.find")).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));check(!editor.Current.Search.IsClosed,"Search menu opens the editor search panel");editor.Current.Search.Close();var originalDoc=editor.Current;var selectors=AdvancedToolsTests.Visual<ComboBox>(editor).ToArray();var encoding=selectors.Single(x=>x.Items.Count==6);var ending=selectors.Single(x=>x.Items.Count==3);encoding.SelectedIndex=3;ending.SelectedIndex=1;var second=EditorTextFile.New();second.Path=@"D:\Example\Notes.txt";second.Text="Example";editor.Add(second);check(encoding.SelectedIndex==5&&ending.SelectedIndex==0,"New document has independent encoding and line-ending choices");editor.Tabs.SelectedItem=originalDoc.Tab;check(encoding.SelectedIndex==3&&ending.SelectedIndex==1,"Switching tabs restores document-specific output choices");editor.UpdateLayout();NextStageTests.Draw(editor,Path.Combine(root,"editor-menu.png"));foreach(var document in editor.Documents){document.FormatModified=false;document.Editor.IsModified=false;}editor.Close();editor=null;
   File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL: "+ex+Environment.NewLine+String.Join(Environment.NewLine,checks));return 1;}finally{if(converter!=null)converter.Close();if(editor!=null){foreach(var doc in editor.Documents){doc.FormatModified=false;doc.Editor.IsModified=false;}editor.Close();}}}
 }
